check("manifest:storage", /storage/.test(manifestText), "bindings persist locally");
check("profile:persistent", /chrome\.storage|browser\.storage|storage\.local/.test(profile), "binding profiles persist");
check("profile:multiRoute", /bachata-generic-binding-store-v1/.test(background) && /profiles: GenericBindingProfile\[\]/.test(background) && /maximumProfilesPerOrigin/.test(background), "multiple route-scoped binding profiles can coexist on one origin");
