check("profile:contentDelegates", /BACHATA_GENERIC_PROFILE_LIST/.test(profile) && /BACHATA_GENERIC_PROFILE_UPSERT/.test(profile) && /chrome\.runtime\.sendMessage/.test(profile), "content scripts delegate shared binding-profile mutations to the background owner");
check("profile:structuralGuard", /isLocatorRecipe/.test(genericTypes) && /isGenericBindingProfile/.test(genericTypes) && /isGenericBindingProfile\(value, origin\)/.test(background) && /isGenericBindingProfile\(value, location\.origin\)/.test(profile), "stored generic profiles and every nested locator recipe share the same structural validation guard in background and content");
check("locator:accessible", /computeAccessibleName/.test(locator), "locators use accessible names");
check("locator:fallback", /finder/.test(locator), "verified elements may store a CSS fallback");
check("candidates:bounded", /slice|MAX|maxCandidates/.test(candidates), "candidate enumeration is bounded");
check("candidates:broadSignals", /data-testid/.test(candidates) && /aria-live/.test(candidates) && /conversation|messages|thread/.test(candidates), "generic candidate discovery covers common semantic test-id, live-region, and conversation containers without free-form selectors");
check("healing:idsOnly", /composerIds|conversationRootIds/.test(healing) && /unknown|allowed/i.test(healing), "healing accepts supplied candidate IDs only");
check("healing:roleCompatible", /idsMatchRole/.test(healing) && /candidateMatchesRole/.test(healing) && /interpretableUnknown/.test(healing) && /candidate\.accessibleName/.test(healing) && /candidate\.textPreview/.test(healing) && /new Set\(ids\)\.size !== ids\.length/.test(healing) && /sendButtonIds, ["']sendButton["']/.test(healing) && /newConversationButtonIds, ["']newConversationButton["']/.test(healing), "healing accepts distinct known role matches or labeled structurally compatible unknown controls while rejecting known conflicts and duplicate cross-role assignments");
check("healing:localizedControls", /healedElementMatchesRole/.test(generic) && /healWithLocalModel/.test(generic) && /No valid new-conversation control/.test(generic), "generic fresh and transient lifecycle control discovery can use bounded local-model healing for localized or icon-only controls");
check("healing:optionalSend", /optionalSendHealingDocumentKey/.test(generic) && /if \(!profile\.sendButton\)/.test(generic) && /profile = await resolveProfile\(\)/.test(generic), "generic sending attempts bounded selector healing once per document before falling back to synthetic Enter when no send control is bound");
check("healing:sameBoundedSet", /DOM_HEALING_CANDIDATE_LIMIT = 24/.test(healing) && /slice\(0, DOM_HEALING_CANDIDATE_LIMIT\)/.test(healing) && /DOM_HEALING_CANDIDATE_LIMIT/.test(localModel), "prompt construction, parser acceptance, and local-model candidate selection share one DOM-healing bound");
check("locator:semanticStructuralFallback", /locatorRecipeMatchesElement/.test(locator) && /structural && isVisibleElement\(structural\) && locatorRecipeMatchesElement\(recipe, structural\)/.test(locator), "structural fallback must still match the saved semantic locator recipe");
