const schemaGuard = read("src/content/generic/schemaGuard.ts");
// BR-G6-01. Content scripts are evaluated under the host page's CSP, so schema validation
// has to be interpreted, never compiled. The bundle-level proof that nothing generates code
// from a string lives in `tests/genericSchemaGuard.test.mjs`, which reads the built file.
check("healing:validated", /createSchemaValidator\(schema\)/.test(healing) && /createSchemaValidator\(responseSchema\)/.test(healing) && /jsonrepair/.test(healing), "both healing contracts are schema validated and one repair is attempted");
check("healing:noCodeGeneration", !/\bnew Function\b/.test(schemaGuard) && !/from "ajv"/.test(healing) && /Object\.hasOwn/.test(schemaGuard), "schema validation is interpreted, never compiled, and closed over own keys only");
// BR-G6-06. Node identity is not ownership: an SPA that recycles message nodes leaves the
// anchor connected and in the same root while the turn underneath becomes another
// conversation's. The nonce is rechecked every pass and again after the last await.
check("generic:continuousNonceOwnership", /const anchorHoldsNonce = \(promptElement: Element, nonce: string\): boolean =>/.test(capture) && /!anchorHoldsNonce\(promptElement, requestNonce\)\s*\n\s*\) \{/.test(capture) && /assertCurrentConversation\?\.\(\);\s*\n\s*const finalRoot = resolveRoot\(\);[\s\S]{0,400}!anchorHoldsNonce\(promptElement, requestNonce\)[\s\S]{0,200}!finalRoot\.contains\(chosen\)/.test(capture), "generic capture rechecks nonce ownership every pass and revalidates the conversation, the anchor and the response node before finalizing");
// BR-G6-07. A new document token, a bumped revision and a changed URL are churn. A reset over a
// conversation that still has its turns on the page is not a fresh conversation.
check("generic:resetNeedsWithdrawnConversation", /const previousConversationWithdrawn = observation\.beforeMessageCount === 0\s*\n\s*\|\| observation\.currentTextLength === 0\s*\n\s*\|\| textReset;/.test(freshConversation) && /&& previousConversationWithdrawn/.test(freshConversation), "an explicitly requested reset is attested only once the conversation it replaced has withdrawn");
// BR-G6-12. A control a person bound is not re-judged on shape, but it may not become a
// *different* known control: a Stop recipe resolving onto Send reads as generation in progress
// on an idle page, and interrupting the turn would click Send and submit the composer.
check("generic:boundControlRoleConflict", /const hint = classifyDomElement\(element\);\s*\n\s*return hint === role\s*\n\s*\|\| \(hint !== "sendButton" && hint !== "stopButton" && hint !== "newConversationButton"\);/.test(generic), "a user-bound control is refused once the page presents it as a different known control");
// BR-G6-14. The admission deadline is one check; every wait after it is a chance for the
// deadline to pass before the irreversible click.
check("generic:deadlineRevalidatedBeforeSend", /const assertRequestStillSendable = \(/.test(generic) && /if \(now\(\) >= request\.deadlineAt\) \{[\s\S]{0,200}rememberCancellation\(request\.requestId\);[\s\S]{0,200}deadline expired before submission/.test(generic) && /assertRequestStillSendable\(request\);[\s\S]{0,200}submitted = true;[\s\S]{0,200}activeSend\.click\(\);/.test(generic), "the generic send re-reads its deadline wherever it re-reads document identity, including immediately before the click");
// BR-G6-11. A refused duplicate send never registered anything, so it may not remove the id it
// collided with: that registration belongs to the turn already running.
check("background:duplicateSendKeepsIncumbent", /if \(registered\) \{\s*\n\s*removeActiveRequest\(request\.requestId\);\s*\n\s*rememberRecovery\(request, "failure"\);\s*\n\s*\}/.test(backgroundIndex), "a refused send removes only a request it registered itself");
// BR-G6-10. Disconnect and re-pair both drop the socket before its close listener runs, so the
// listener's queue cancellation never fires for them. A provisioning left running keeps opening
// and navigating a tab for a request the new server never made.
check("background:provisioningCancelledOnPairing", /if \(input\.type === "popup\.pair"\)[\s\S]{0,1600}provisioningQueue\.cancelAll\(\);[\s\S]{0,200}await stopActiveRequests\(\);/.test(backgroundIndex) && /if \(input\.type === "popup\.disconnect"\) \{[\s\S]{0,400}provisioningQueue\.cancelAll\(\);[\s\S]{0,120}await stopActiveRequests\(\);/.test(backgroundIndex), "re-pairing and disconnecting cancel provisioning before they abandon the socket it would answer on");
// BR-G6-15. The popup validates the whole state as one value, so a single field over its limit
// shows the user nothing at all. Producer and consumer read the same numbers rather than keeping
