check("popup:sharedBounds", /export const POPUP_LIMITS = \{[\s\S]{0,400}tabs: 200,/.test(popupProjection) && /const withSelectedTab = <T extends \{ id: number \}>/.test(popupProjection) && /return withSelectedTab\(tabs, selectedTabId\)\.map/.test(popupProjection) && /tabs: withSelectedTab\(input\.tabs, input\.selectedTabId\)/.test(popupProjection) && /\[selected, \.\.\.kept\.slice\(0, POPUP_LIMITS\.tabs - 1\)\]/.test(popupProjection) && !/\n  return tabs\.slice\(0, POPUP_LIMITS\.tabs\)/.test(popupProjection) && /bounded\(tab\.title, POPUP_LIMITS\.title\)/.test(popupProjection) && /import \{[^}]*\bPOPUP_LIMITS\b[^}]*\} from "\.\.\/background\/popupProjection\.js";/.test(popupEntry) && /const maximumPopupTabs = POPUP_LIMITS\.tabs;/.test(popupEntry) && /const textLimits = POPUP_LIMITS;/.test(popupEntry), "the popup projection and the popup enforce one set of bounds, and the bound conversation is pinned into the projection before the tab cap is applied, so a selection past the cap is never reported without the row and the Unbind control that act on it");
check("generic:boundedHealing", /maximumHealingAttempts/.test(generic) && /healingRetryDelayMs/.test(generic) && /healingDocumentKey/.test(generic) && /canonicalConversationUrl\(\)/.test(generic), "auto-heal uses bounded retries scoped to the exact live document and canonical route");
check("generic:randomDocumentToken", /generic-document:\$\{crypto\.randomUUID\(\)\}/.test(generic) && /documentToken/.test(background), "each loaded generic document receives a random token carried through registration and status");
check("generic:singleHealingFlight", /healingInFlight/.test(generic) && /if \(healingInFlight\) return false/.test(generic) && /finally \{[\s\S]{0,100}healingInFlight = false/.test(generic), "repeated readiness probes cannot launch overlapping full auto-heal requests in one document");
check("generic:transientStopCapability", /learnTransientStopBinding/.test(generic) && /const current = profile\.stopButton \? resolveLocatorRecipe/.test(generic) && /isActiveControl\(current\)/.test(generic) && /classifyDomElement\(entry\.element\) === ["']stopButton["']/.test(generic), "a stale or absent transient Stop locator is rediscovered from the live generation controls");
// N1, REVIEW-11. `Date.now()` is no longer read directly in these loops: the clock is named
// once in `transientControl.ts` as `now()` so a test can substitute it, and `realScheduler` is
