check("generic:evidenceBasedLifecycleCapability", /profileHasVerifiedLifecycle/.test(generic) && /profileHasConfirmedInterruption/.test(generic) && /completion: lifecycleReady \? ["']verifiedLifecycle["'] : ["']manualOnly["']/.test(generic) && /interruption: interruptionReady \? ["']confirmed["'] : ["']unavailable["']/.test(generic) && /lifecycleCompletedFingerprint/.test(lifecycleEvidence) && /interruptionConfirmedFingerprint/.test(lifecycleEvidence), "generic completion and interruption capabilities require recent route- and locator-bound lifecycle evidence rather than a stored Stop recipe alone");
check("generic:fullStopLearningWindow", /waitForTransientControl/.test(generic) && /deadlineAt = now\(\) \+ Math\.max\(1, probe\.timeoutMs\)/.test(transientControl) && /while \(now\(\) <= deadlineAt\)/.test(transientControl) && /probe\.collectHeuristicCandidates\(\)/.test(transientControl) && !/Math\.min\(timeoutMs, 1_000\)/.test(generic), "generic Stop discovery keeps rescanning the live DOM for the complete configured learning window");
check("generic:dynamicStopSubmit", /\(stop && !autoHealedElementMatchesRole\(profile, stop, ["']stopButton["']\)\)/.test(generic) && /const activeStop = resolveLocatorRecipe/.test(generic), "prompt submission accepts a stop control that is absent while idle and validates it when generation exposes it");
check("generic:routeScoped", /routePatternMatches/.test(profile) && /currentRoutePattern/.test(profile), "saved generic bindings are enforced against the current route");
check("generic:fullRouteIdentity", /location\.pathname.*location\.search.*location\.hash/.test(profile) && !/url\.hash/.test(genericConversationBranch) && /return url\.toString\(\)/.test(genericConversationBranch), "generic bindings and conversation identity preserve hash-router and query route identity");
check("generic:runtimeHealth", /const bindingInvalid =/.test(generic) && /!cancelled && bindingInvalid/.test(generic) && /markProfileValidation\(profile, false/.test(generic), "only binding-invalid outcomes degrade generic selector health; cancellation and provider failures stay neutral");
check("generic:exactSubmissionIdentity", /documentToken: string; documentRevision: number; conversationUrl: string; conversationIdentity: string/.test(genericTypes) && /assertRequestMatchesCurrentDocument\(request\)/.test(generic) && /activeSend\.click\(\)/.test(generic), "generic sends carry and recheck exact document and conversation identity before the irreversible submission action");
check("generic:stickyPreSubmitCancel", /acceptingRequestIds/.test(generic) && /cancelledRequestIds/.test(generic) && /rememberCancellation/.test(generic) && /submissionPrevented: true/.test(generic) && /message\.type === ["']conversation\.interrupt["'][\s\S]{0,320}active && interruptMatchesRequest\(message, active\)[\s\S]{0,260}pendingInterrupts\.add\(message\.requestId\)[\s\S]{0,360}handleServerMessage\(message, nextSocket\)/.test(backgroundIndex) && /ensureContent: false/.test(backgroundIndex), "interruption remains sticky before dispatch and can bypass an active provider send while content-side submission is still cancellable");
// BB-4. Remembering an interrupt that arrives before a send has committed is one implementation
