check("builtin:stickyPreSubmitCancel", /const createInterruptHandler = \(hooks: BachataInterruptHandlerHooks\)/.test(providerLogic) && /const active = hooks\.activeRequest\(\);/.test(providerLogic) && /if \(!active\) \{[\s\S]{0,160}hooks\.rememberPreSubmit\(request\.requestId\);[\s\S]{0,120}hooks\.cancelHealing\(\);[\s\S]{0,80}return \{ interrupted: true \};/.test(providerLogic) && /if \(!active\.submissionCommitted\) \{[\s\S]{0,160}hooks\.rememberPreSubmit\(request\.requestId\);[\s\S]{0,120}hooks\.cancelHealing\(\)/.test(providerLogic) && [chatgptContent, claudeContent].every((source) => /createCancellationRegistry\(\{[\s\S]{0,160}isActive:/.test(source) && /rememberPreSubmit: \(requestId\) => cancelledRequests\.rememberPreSubmit\(requestId\)/.test(source) && /cancelledRequests\.has\(request\.requestId\)[\s\S]{0,180}interrupted before submission/.test(source)), "ChatGPT and Claude remember an interrupt that races ahead of content-side send dispatch and reject the later send");
