check("builtin:boundedPreSubmitCancel", /const createCancellationRegistry = \(/.test(providerLogic) && /preSubmitTtlMs = options\.preSubmitTtlMs \?\? 30_000/.test(providerLogic) && /if \(!options\.isActive\(requestId\)\)[\s\S]{0,80}cancelled\.delete\(requestId\)/.test(providerLogic) && [chatgptContent, claudeContent].every((source) => !/new Set<string>\(\);\n\/\/ A pre-submit interrupt/.test(source)), "the pre-submit cancellation bound lives once, in the shared provider logic, instead of a copy per provider");
check("builtin:finalPreSubmitAttestation", [chatgptContent, claudeContent].every((source) => /const assertPreSubmitState = async \(expectedComposerText\?: string, button\?: HTMLElement\)/.test(source) && /Date\.now\(\) >= request\.deadlineAt/.test(source) && /await ensureConversationBinding\(request\)/.test(source) && /await assertPreSubmitState\(\)[\s\S]{0,900}writeComposer\(element, request\.text\)[\s\S]{0,180}await assertPreSubmitState\(request\.text\)[\s\S]{0,420}await assertPreSubmitState\(request\.text, button\)[\s\S]{0,100}submissionCommitted = true[\s\S]{0,80}button\.click\(\)/.test(source)), "built-in providers attest an untouched composer before injection, verify exact prompt readback after injection, and re-attest cancellation, deadline, conversation, composer, and Send immediately before click");
// BR-G6-02, reopened twice. The refusal that fires because a person's draft is in the composer
// must not be the thing that deletes it, and the withdrawal that takes back this request's own
