check("builtin:refusalOwnsOnlyItsOwnInsertion", /const ownsNothing = \(ownership: ComposerOwnership\)/.test(providerLogic) && /ownership\.text === undefined && ownership\.attachments === undefined/.test(providerLogic) && /if \(ownsNothing\(ownership\)\) \{[\s\S]{0,80}return \{ submitted: false, error \};/.test(providerLogic) && /if \(hooks\.readComposer\(element\) === ownership\.text\) \{[\s\S]{0,80}hooks\.writeComposer\(element, ""\);[\s\S]{0,80}\} else \{[\s\S]{0,40}ambiguous = true;/.test(providerLogic) && !/const planControlWithdrawal = \(/.test(providerLogic) && !/\.click\(\)/.test(providerLogic.split("const cleanupComposer")[1]?.split("const rejectBeforeSubmission")[0] ?? "") && /owned\.files\.length < owned\.expected/.test(providerLogic) && /ownership\.baseline = \{ before: attachmentRemovalControls\(element\), expected \};/.test(providerLogic) && !/attachments = \{[\s\S]{0,60}files: \[\][\s\S]{0,60}\};/.test(providerLogic.split("const captureAttachmentBaseline")[1]?.split("const commitAttachmentOwnership")[0] ?? "") && /options\.onBeforeWrite\?\.\(\);\s*\n\s*setter\.call\(options\.input, transfer\.files\);/.test(providerLogic) && !/abandonAttachmentOwnership/.test(providerLogic) && /\.filter\(\(file\) => !owned\.includes\(file\)\)/.test(providerLogic) && /stagedFiles\(\)\.every\(\(file\) => !owned\.files\.includes\(file\)\) &&\s*\n\s*attachmentRemovalControls\(element\)\.every\(\(button\) => before\.has\(button\)\)/.test(providerLogic) && /if \(ambiguous\) \{[\s\S]{0,40}return false;/.test(providerLogic) && !/resetAttachmentInput\(\);/.test(providerLogic.split("const cleanupComposer")[1] ?? "") && [chatgptContent, claudeContent].every((source) => /const composerOwnership: ComposerOwnership = \{\};/.test(source) && /captureAttachmentBaseline\(element, composerOwnership, request\.attachments\.length\);\s*\n\s*await attachImages\(\{/.test(source) && /onStaged: \(files\) => recordStagedFiles\(composerOwnership, files\),/.test(source) && /onStaged\?\.\(staged\);/.test(providerLogic) && /onBeforeWrite: \(\) => commitAttachmentOwnership\(composerOwnership\),/.test(source) && /recordInsertedText\(composerOwnership, request\.text\);\s*\n\s*writeComposer\(element, request\.text\);/.test(source)), "attachment ownership begins at the write and not before it: the pre-staging reading takes no claim, the claim is committed as the statement immediately before the native setter, and every failure above that line owns nothing, so it neither cleans nor blocks the composer. A pre-submit refusal withdraws only what this request still demonstrably owns: the composer text only while it is byte-for-byte the insertion, and the provider input rebuilt around the exact File objects this request placed. No removal control is clicked at all — a filename is metadata, not identity — so a withdrawal is proved by the input and by every control that appeared since staging began going away, and an unproved one blocks the document instead");
