check("protocol:genericAttestedSession", /candidate\.conversationUrl === attestation\.conversationUrl/.test(routerState) && /candidate\.conversationIdentity === attestation\.conversationIdentity/.test(routerState) && /sessionForAttestation\(await buildSessions\(\), tabId, attestation, state\)/.test(backgroundIndex) && /finalSession\.conversationUrl/.test(backgroundIndex), "the response is published against the final attested generic session rather than the stale pre-submission route");
